entries[461130] = { ["name"] = "Tiefsitzende Stärke", ["text"] = "Sofort\nUnheilig\nWenn 'Hereinbrechende Verdammnis verbraucht wird, erlangt Ihr 8 lang 5 Sek.% Stärke.\n\nWenn 'Geißelstoß' 'Virulente Seuche' verbraucht, kostet Euer nächster Ausbruch keine Runen und wirkt 'Todesmantel' oder 'Epidemie' mit 100% Effektivität, je nachdem, was Ihr zuletzt gezaubert habt..\n\nBlut\nWenn 'Scharlachrote Geißel' verbraucht wird, erlangt Ihr 12 lang 12 Sek.% Stärke.\n\nWenn 'Siedendes Blut' 2 oder mehr Ziele trifft, erzeugt es 1 Aufladungen von 'Knochenschild'." }
entries[461134] = { ["name"] = "Aaskäfer", ["text"] = "Wirken in 3 sek.\nDer Zaubernde sondert Pheromone ab, die ihm einen nerubischen Käfer zu Hilfe rufen." }
entries[461135] = { ["name"] = "Hereinbrechende Verdammnis", ["text"] = "Sofort\nEure automatischen Angriffe haben eine Chance von 25%, Euren nächsten Einsatz von 'Todesmantel' [ Epidemie : oder 'Epidemie' ] kritisch treffen zu lassen.\n\nZusätzlich kostet Euer nächster Einsatz von 'Todesmantel' 10 weniger Runenmacht und lässt 1 'Schwärende Wunde' bersten." }
