entries[461242] = { ["name"] = "Lebhafte Totems", ["text"] = "Sofort\n[ Verstärkung : 'Lavapeitsche' hat eine Chance, ein Totem der Verbrennung zu beschwören, das 'Sengende Blitze' schleudert, die Gegnern in der Nähe (65.205% der Zaubermacht) Feuerschaden zufügen. Hält 8 Sek. lang an.\n\n'Frostschocks', die durch 'Hagelsturm', 'Lavapeitsche' oder 'Feuernova' ermächtigt wurden, lassen Eure 'Totems der Verbrennung' eine 'Verbrennende Salve' auf bis zu 5 Gegner in der Nähe schleudern, die (92.736% der Zaubermacht) Feuerschaden verursacht /\n\nWiederherstellung\nWenn Ihr ein 'Totem der Heilungsflut', 'Totem des heilenden Flusses', 'Totem des Wolkenbruchs', oder 'Totem der Geistverbindung' beschwört, zaubert Ihr einen kostenlosen Spontanzauber von 'Kettenheilung' mit 100% Effektivität ]" }
entries[461243] = { ["name"] = "Schutz des Lichts", ["text"] = "Verbündete unter dem Einfluss von 'Flamme des Glaubens' erleiden 5% weniger Schaden." }
entries[461244] = { ["name"] = "Überfließendes Licht", ["text"] = "30% der überschüssigen Heilung von 'Heiliger Schock' werden in einen Absorptionsschild umgewandelt, der bis zu 10% Eurer maximalen Gesundheit beträgt." }
entries[461245] = { ["name"] = "Funkelndes Strahlen", ["text"] = "Beim Verbrauchen von Heiliger Kraft besteht eine Chance von 25%, den Absorptionseffekt von 'Vom Licht gerettet' mit einer Effektivität von 33% auszulösen, ohne die Abklingzeit des Zaubers zu aktivieren.\n(750ms Abklingzeit)" }
entries[461246] = { ["name"] = "Glorreiche Dämmerung", ["text"] = "'Heiliger Schock' hat eine Chance von 12%, beim Einsatz eine Aufladung zu erstatten, und seine Heilung ist um 10% erhöht." }
entries[461248] = { ["name"] = "Hochspannung", ["text"] = "Wenn 'Arkane Geschosse' Schaden verursacht, besteht eine Chance von 10%, Euch 1 Arkane Aufladung zu gewähren.\n\nDie Chance wird jedes Mal, wenn Ihr durch 'Arkane Geschosse' keine Arkane Aufladung erhaltet, um 15% erhöht." }
entries[461250] = { ["name"] = "Licht der aufgehenden Sonne", ["text"] = "[ Kreuzzug der Vergeltung : Nachdem Ihr 'Kreuzzug der Vergeltung' eingesetzt habt, wird Euer nächster Einsatz von 'Heiliger Schock' 2 weitere Male eingesetzt / Nachdem Ihr 'Zornige Vergeltung' eingesetzt habt, werden Eure nächsten 2 Einsätze von 'Heiliger Schock' 2 weitere Male eingesetzt.]\nNachdem Ihr 'Göttlicher Glockenschlag' eingesetzt habt, werden Eure nächsten 2 Einsätze von 'Heiliger Schock' 2 weitere Male eingesetzt." }
entries[461257] = { ["name"] = "Statische Wolke", ["text"] = "Immer, wenn Ihr 'Arkane Explosion' einsetzt, erhöht sich der Schaden des Zaubers um 25%.\n\nDer Bonus wird zurückgesetzt, nachdem 100% Schaden erreicht wurden." }
entries[461260] = { ["name"] = "Spielerei des Konsortiums", ["text"] = "Verringert die Manakosten von 'Arkanschlag' um 5% und erhöht den Schaden der Fähigkeit um 8%." }
entries[461261] = { ["name"] = "Hirnschmalz", ["text"] = "Wenn Ihr 'Freizaubern' erhaltet, wird Eure Intelligenz 8 Sek. lang um 1% erhöht. Mehrere Instanzen können sich überlappen." }
entries[461264] = { ["name"] = "Netherflux", ["text"] = "Ersetzt Berührung der Magi\n40 Meter Reichweite\nSofort 15 sek. Abklingzeit\nBrandmarkt Euer Ziel, wodurch der Schaden, den es durch Euren nächsten gezielten Zauber erleidet, um 40% erhöht wird.\n\nErzeugt 4 Arkane Aufladungen." }
entries[461273] = { ["name"] = "Wahrheit obsiegt", ["text"] = "'Richturteil' heilt Euch um (240% der Zaubermacht) Gesundheit und kostet 30% weniger Mana. 50% der überschüssigen Heilung dieses Effekts wird auf 2 Verbündete innerhalb von 40 Metern übertragen." }
entries[461278] = { ["name"] = "Vollendung", ["text"] = "Die Chance, mit 'Wort der Herrlichkeit' und 'Licht der Morgendämmerung' kritisch zu heilen, wird, basierend auf der aktuellen Gesundheit des Ziels, um bis zu 30% erhöht. Ziele mit niedriger Gesundheit haben eine höhere Chance, kritisch geheilt zu werden." }
entries[461281] = { ["name"] = "Relikt von Uldum", ["text"] = "Unbegrenzte Reichweite\nSofort\nBrann schwingt ein mächtiges uraltes Relikt, das heilige Energie ausstrahlt und Verbündete 20 Sek. lang alle 1 Sek. um eine erhebliche Menge Gesundheit heilt." }
entries[461287] = { ["name"] = "Befreiung", ["text"] = "'Wort der Herrlichkeit' und 'Licht der Morgendämmerung' haben eine Chance in Höhe Eures Tempos, die Kosten Eures nächsten Einsatzes von 'Heiliges Licht', 'Kreuzfahrerstoß' oder 'Richturteil' um 6000 zu verringern.\n(1s Abklingzeit)" }
entries[461288] = { ["name"] = "Blutbad", ["text"] = "Sofort\nDas Aktivieren von 'Tollkühnheit' gewährt 50 Wut, und während 'Tollkühnheit' aktiv ist, werden 'Wütender Schlag' und 'Blutdurst' durch 'Schmetterschlag' und 'Blutbad' ersetzt.\n\nSchmetterschlag\nFührt einen mächtigen Schlag mit beiden Waffen aus, der insgesamt [(258.746% der Angriffskraft) + (258.746% der Angriffskraft)] körperlichen Schaden verursacht.\n\n'Schmetterschlag' hat eine Chance von 25%, seine eigene Abklingzeit sofort abzuschließen, und seine kritischen Treffer verursachen 20% mehr Schaden.\n\nErzeugt 12 Wut.\n\nBlutbad\nGreift das Ziel in einer blutrünstigen Raserei an, fügt ihm (385.641% der Angriffskraft) körperlichen Schaden zu und stellt 3% Eurer Gesundheit wieder her.\n\n'Blutbad' lässt das Ziel bluten und fügt ihm so (60% der Angriffskraft) Schaden im Verlauf von 6 Sek. zu. Der Einsatz von 'Blutbad' bei einem Ziel, das bereits davon betroffen ist, verlängert den Blutungseffekt um 6 Sek.\n\nErzeugt 8 Wut." }
entries[461310] = { ["name"] = "Schrott tragen", ["text"] = "300 Meter Reichweite\nSofort\nTragt ein Schrottteil.\nKehrt zum Uhrwerkschrottsammler zurück, um eine Belohnung zu erhalten." }
