entries[461389] = { ["name"] = "Belohnung: Flamme und Münze", ["text"] = "Kanalisiert (Wirken in 8 sek.)\nDas Einwerfen einer Flammenmarke und einer Münzmarke führt dazu, dass der einarmige Bandit 8 Sek. lang alle 0.5 Sek. glühend heiße Münzen auf alle Spielercharaktere verschießt. Diese Münzen verursachen 6 Sek. lang alle 0.5 Sek. 251553 Feuerschaden. Dieser Effekt ist stapelbar." }
entries[461390] = { ["name"] = "Flamme und Münze", ["text"] = "Sofort\nDas Einwerfen einer Flammenmarke und einer Münzmarke führt dazu, dass der einarmige Bandit 8 Sek. lang alle 0.5 Sek. glühend heiße Münzen auf alle Spielercharaktere verschießt. Diese Münzen verursachen 6 Sek. lang alle 0.5 Sek. 251553 Feuerschaden. Dieser Effekt ist stapelbar." }
