entries[461395] = { ["name"] = "Belohnung: Münze und Bombe", ["text"] = "Sofort\nDas Einwerfen einer Münzmarke und einer Bombenmarke führt dazu, dass mehrere vergoldete Premiumdynamitbeuten herbeigerufen werden. Die Premiumwährung erhöht die Gesundheit um 75% und den verursachten Schaden um 50% und gewährt Immunität gegen Kontrollverlust- und Unterbrechungseffekte." }
entries[461401] = { ["name"] = "Kollabierende Nova", ["text"] = "300 Meter Reichweite\nSofort\nWenn ein kosmisches Simulakrum sich innerhalb von 8 Metern um ein anderes Simulakrum befindet, reagieren sie aufeinander und verbrennen, was allen Spielercharakteren 1439079 Schattenschaden zufügt." }
entries[461404] = { ["name"] = "Chistoß", ["text"] = "40 Meter Reichweite\nWirken in 1 sek. 0.1 sek. Abklingzeit\nSchleudert einen Schwall Chienergie bis zu 40 Meter vorwärts, wobei er allen Gegnern in seinem Weg (280% der Angriffskraft) Naturschaden zufügt und den Mönch sowie alle Verbündeten im Effektbereich um (220% der Angriffskraft) Gesundheit heilt. Schaden und Heilung bei Zielen über 5 Ziele hinaus verringert.\n[ Braumeister : Beim Einsatz von 'Chistoß' sind Vermeidungsmechaniken weiterhin aktiv ]" }
