entries[461408] = { ["name"] = "Verschlingen", ["text"] = "Unbegrenzte Reichweite\nSofort\nAnsurek verschlingt die Essenz ihres Opfers und fügt ihm 115126303 Schattenschaden zu." }
entries[461409] = { ["name"] = "Fass!", ["text"] = "Sofort\nDie Chance, dass 'Tötungsbefehl' 'Todesstoß' auslöst, ist um 5% erhöht, und 'Todesstoß\" sorgt jetzt dafür, dass 'Tödlicher Schuss' bis zu 2 zusätzliche Ziele trifft.\n\nEure Chance, 'Todesstoß' zu erhalten, ist während 'Koordinierter Angriff' doppelt so hoch.\n\nTodesstoß\nDie Abklingzeit von 'Tödlicher Schuss' wird zurückgesetzt. Euer nächster Einsatz von 'Tödlicher Schuss' kann gegen jedes Ziel unabhängig von seiner aktuellen Gesundheit eingesetzt werden." }
entries[461425] = { ["name"] = "Aktivieren" }
entries[461426] = { ["name"] = "Complete Tracking Quest" }
entries[461431] = { ["name"] = "Handzettel gegen Gallywix", ["text"] = "20 Meter Reichweite\nWirken in 1 sek. 6 sek. Abklingzeit\nVerteilt Handzettel, um Bürger über den Plan, Gallywix zu erledigen, zu informieren!" }
entries[461432] = { ["name"] = "Ewige Flamme", ["text"] = "40 Meter Reichweite\nSofort\nHeilt einen Verbündeten um (315% der Zaubermacht) Gesundheit sowie im Verlauf von 16 Sek. zusätzlich um (91.2% der Zaubermacht) Gesundheit.\n\nDie Heilung ist um 25% erhöht, wenn Ihr Euch selbst heilt." }
