entries[461793] = { ["name"] = "G.R.W.", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Zaubernde verschießt eine Raketensalve aus seinem G.R.W., die Spielercharakteren innerhalb von 8 Metern um den Einschlag 40 Feuerschaden zufügt.\n\nDanach muss der G.R.W. nachgeladen werden." }
entries[461796] = { ["name"] = "Nachladen", ["text"] = "Wirken in 7 sek.\nDer Zaubernde lädt seinen G.R.W. nach, um eine weitere Salve vorzubereiten." }
entries[461797] = { ["name"] = "Im Rhythmus", ["text"] = "Sofort\nSikran kommt richtig in den Rhythmus des Kampfs, was den Schaden von ' Phasenklingen ' um 10% erhöht.\nDieser Effekt ist stapelbar." }
