entries[461800] = { ["name"] = "Geschrumpft!", ["text"] = "30 Meter Reichweite\nWirken in 1 sek. 5 sek. Abklingzeit\nSchockt eine Kreatur, um sie zu schwächen und sie um 50% zu schrumpfen! Hält 30 Sek. lang an.\n\nFunktioniert nur in den Glücksmomentminen." }
entries[461805] = { ["name"] = "Geladen und entsichert", ["text"] = "Sofort\nDer Zaubernde lädt seinen G.R.W., um eine Salve Raketen abzufeuern." }
entries[461814] = { ["name"] = "Schattenschlag", ["text"] = "8 Meter Reichweite\nWirken in 2 sek.\nTrifft das Ziel mit einer schattenerfüllten Klinge und fügt ihm so Schattenschaden sowie zusätzlich 8 Sek. lang alle 2 Sek. Schattenschaden zu." }
