entries[461817] = { ["name"] = "Wirbelnde Klingen", ["text"] = "Wirken in 4 sek.\nDer Zaubernde wirbelt 5 Sek. lang im Kreis herum, fügt Spielercharakteren innerhalb von 5 Metern alle 1 Sek. körperlichen Schaden zu und stößt sie zurück." }
entries[461818] = { ["name"] = "Glücksmünze", ["text"] = "30 Meter Reichweite\nSofort\nWirft immer, wenn ein Finishing-Move 5 oder mehr Combopunkte verbraucht, eine schicksalsgebundene Münze. Kopf erhöht den Schaden Eurer Angriffe 15 Sek. lang, oder bis Ihr Zahl werft, um 10%. Zahl fügt Eurem Ziel (210% der Angriffskraft) kosmischen Schaden zu.\n\nImmer wenn der Wurf das gleiche Ergebnis wie der vorherige Wurf hat, wird bei Kopf der Schaden um zusätzliche 2% und bei Zahl der Schaden um 10% erhöht." }
entries[461819] = { ["name"] = "Wirbelnde Klingen", ["text"] = "40 Meter Reichweite\nSofort\nDer Zaubernde wirbelt 5 Sek. lang im Kreis herum, fügt Spielercharakteren innerhalb von 5 Metern alle 1 Sek. körperlichen Schaden zu und stößt sie zurück." }
