entries[461834] = { ["name"] = "Glyphe des Schreckens", ["text"] = "100 Meter Reichweite\nSofort\nCa. 20 Procs pro Minute\nDas Entschlüsseln der Glyphe erfüllt den Leser mit Schrecken, sodass seine Angriffe und Zauber eine Chance haben, 'Schreckensblitz' gegen sein aktuelles Ziel zu entfesseln.\n\nSchreckensblitz :\nVerursacht 10 Schattenschaden." }
entries[461836] = { ["name"] = "Kerzenwurf", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde wirft eine Kerze auf das Ziel. Verursacht Feuerschaden und verbrennt das Ziel, um ihm 8 Sek. lang alle 2 Sek. zusätzlichen Feuerschaden zuzufügen." }
