entries[461842] = { ["name"] = "Triefendes Schmettern", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nDas Koaglamat schmettert auf sein aktuelles Ziel, fügt ihm 8485573 Schattenschaden zu und verringert seine erhaltene Heilung 10 Sek. lang um 30%." }
