entries[461876] = { ["name"] = "Sickernde Transfusion", ["text"] = "Sofort\nDer blutgebundene Schrecken überträgt das Schwarzblut in seinen Körper und erhöht so seinen verursachten Schaden um 10%. Dieser Effekt ist stapelbar." }
