entries[461879] = { ["name"] = "Wachsgeschoss", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nDer Zaubernde wirft einen Klumpen Wachs auf das Ziel. Verursacht Naturschaden und verringert 8 Sek. lang die Bewegungsgeschwindigkeit um 30%." }
entries[461880] = { ["name"] = "Blutwoge", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nDas Koaglamat brüllt, fügt Spielercharakteren innerhalb von 8 Metern 9697798 Schattenschaden zu und erzeugt an seinem Standort eine größer werdende Lache aus Schwarzblut. Solange Spielercharaktere sich innerhalb dieser Lachen befinden, erleiden sie alle 1 Sek. 1697922 Schattenschaden und ihre Bewegungsgeschwindigkeit wird um 35% verringert." }
