entries[461886] = { ["name"] = "Versteinernder Blick", ["text"] = "Wirken in 3 sek.\nKanalisiert 4 Sek. lang einen versteinernden Blick, der Gegnern innerhalb von 10 Metern vor dem Zaubernden Naturschaden zufügt. Die Bewegungsgeschwindigkeit getroffener Gegner wird für 15 Sek. um 10% verringert.\n\nBeim Erreichen von 5 Stapeln werden Gegner für 3 Sek. ' Versteinert! '." }
