entries[462211] = { ["name"] = "Herzhafter Sushiteller", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nTischt eine Platte mit Delikatessen auf, an der sich alle Spielercharaktere bedienen dürfen!\n\nStellt im Verlauf von 20 Sek. ( 2250000 / 5 * 20) Gesundheit und ( 750000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr Satt und Euer höchster Sekundärwert wird 1 Stunde lang um 470 erhöht." }
entries[462212] = { ["name"] = "Herzhaftes Festmahl des göttlichen Tags", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nTischt ein Festmahl von Mereldar auf, an dem sich alle Spielercharaktere bedienen dürfen!\n\nStellt im Verlauf von 20 Sek. ( 2250000 / 5 * 20) Gesundheit und ( 750000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nSatt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Satt ' und Euer Primärwert wird 1 Stunde lang um 446 erhöht." }
entries[462213] = { ["name"] = "Herzhaftes Festmahl der Mitternachtsmaskerade", ["text"] = "5 Meter Reichweite\nWirken in 1 sek.\nTischt ein Festmahl von Mereldar auf, an dem sich alle Spielercharaktere bedienen dürfen!\n\nStellt im Verlauf von 20 Sek. ( 2250000 / 5 * 20) Gesundheit und ( 750000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben.\n\nZünftig satt\nWenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr ' Zünftig satt ' und Euer Primärwert wird 1 Stunde lang um 446 erhöht." }
