entries[462263] = { ["name"] = "Essenzentzug", ["text"] = "60 Meter Reichweite\nSofort\nDer Zaubernde entzieht Gegnern in der Umgebung die Essenz und fügt so Gegnern innerhalb von 40 Metern 5 Sek. lang alle 1 Sek. 690758 Schattenschaden zu.\n\nJeder getroffene Gegner erhöht den Schattenschaden um 5%." }
