entries[462267] = { ["name"] = "Blutiger Auswurf", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Zaubernde öffnet einen Schwarzblutextraktor und setzt so Wellen von Schwarzblut frei, die alle 5.2 Sek. 0 Schattenschaden verursachen und Gegner zurückdrängen." }
