entries[462269] = { ["name"] = "Säurebolzen tragen", ["text"] = "Sofort\nTrägt einen Säurebolzen .\n\nSäurebolzen :\nVerschießt einen Säurebolzen, der Gegnern innerhalb von 10 Metern 3454209 Naturschaden zufügt und für 12 Sek. eine ätzende Lache hinterlässt, die alle 1 Sek. 287549 Naturschaden verursacht." }
entries[462270] = { ["name"] = "Frostsplitterbolzen tragen", ["text"] = "Sofort\nTrägt einen Frostsplitterbolzen .\n\nFrostsplitterbolzen :\nVerschießt einen Bolzen aus frostigem Schrapnell, der Gegnern innerhalb von 8 Metern 2875492 Frostschaden zufügt. Bei fliegenden Kreaturen erhöht sich dieser Schaden um 400%." }
entries[462271] = { ["name"] = "Stachelbolzen tragen", ["text"] = "Sofort\nTrägt einen Stachelbolzen .\n\nStachelbolzen :\nVerschießt einen Stachelbolzen, der Gegnern innerhalb von 6 Metern 2302526 körperlichen Schaden sowie 20 Sek. lang alle 2 Sek. 287816 zusätzlichen körperlichen Schaden zufügt. Dieser Effekt ist stapelbar." }
entries[462283] = { ["name"] = "Säurewolke", ["text"] = "100 Meter Reichweite\nSofort\nSprüht Säure auf den Standort des Ziels und erzeugt eine Wolke, die 1.5 Min. lang bestehen bleibt und Gegnern in der Nähe alle 1 Sek. 0 Naturschaden zufügt." }
