entries[462305] = { ["name"] = "Schattentor", ["text"] = "Sofort\nSchattenhafte Portale schaffen Ansureks Streitkräfte heran und explodieren dann, was Spielercharakteren innerhalb von 100 Metern 57563151 Schattenschaden zufügt.\n\nDie Reise durch ein Portal verhindert die Explosion, fügt aber dem Reisenden 230253 Schattenschaden zu und belegt ihn mit ' Düstere Berührung ' und ' Schattenhafte Verzerrung '." }
entries[462306] = { ["name"] = "Das Ungehörige", ["text"] = "Sofort\nEine schattenhafte Welt unterhalb der Realität, in der wahre Schrecken lauern." }
