entries[462319] = { ["name"] = "Eruption", ["text"] = "Wirken in 2 sek.\nLord Roccor bricht aus, fügt Gegnern im Effektbereich 1936101 Vulkanschaden zu und erschafft eine Lache brodelnden Magmas. Durch die Eruption entstandenes brodelndes Magma bringt 3 lebende Magmas hervor, die versuchen, zu ihrer Lache zurückzukehren. Mit jedem lebenden Magma, das die Lache erreicht, vergrößert sich diese." }
entries[462320] = { ["name"] = "Feurige Kristallisierung", ["text"] = "Wirken in 12 sek.\nLord Roccor verwandelt sämtliches brodelndes Magma in Obsidianelementare, deren Macht mit der Größe der Lache ansteigt." }
