entries[462527] = { ["name"] = "Citrin des Meeresbodenleviathans", ["text"] = "Gewährt 6 [Quellwert] / 8211.35 Ausdauer und erhöht Eure Größe leicht. Zusätzlich erleiden Angreifer ( 36 * 0.82) Frostschaden, wenn Ihr über mehr als 80% Gesundheit verfügt.", ["unresolvedValues"] = true }
entries[462528] = { ["name"] = "Citrin des legendären Kapitäns", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen zufälligen Effekt eines singenden Citrins mit 150% Effektivität einzusetzen." }
entries[462530] = { ["name"] = "Geweihter Citrin des Seefahrers", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Verbündeten in wiederherstellendem Wasser zu baden, das auf 2 Verbündete in der Nähe überspringt und bei jedem ( 36 * 19.6 * 1 ) Gesundheit wiederherstellt." }
entries[462531] = { ["name"] = "Bardischer Citrin des alten Salzes", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, 5 Verbündeten in der Nähe ein Seemannslied zuzuflüstern und so um ( 36 * 16.34 * 1 ) Gesundheit im Verlauf von 5 Sek. zu heilen." }
entries[462532] = { ["name"] = "Citrin des Sturmkanals", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, einen Verbündeten mit Blitzen abzuschirmen, die 10 Sek. lang die nächsten ( 36 * 29.41 * 1 ) eintreffenden Schaden absorbieren.\n\nSolange der Schild hält, erleiden Angreifer 10% des absorbierten Werts als Naturschaden." }
entries[462534] = { ["name"] = "Runenverzierter Citrin des Windsängers", ["text"] = "Gewährt [Quellwert] Eures höchsten Sekundärwerts.", ["unresolvedValues"] = true }
entries[462535] = { ["name"] = "Runenverzierter Citrin des Tiefenbewohners", ["text"] = "Gewährt 2 [Quellwert] / 1510.13 Meisterschaft.\n\nZusätzlich werden die Effekte aller anderen singenden Citrine abhängig von Eurer gesamten Meisterschaft verstärkt.", ["unresolvedValues"] = true }
