entries[462539] = { ["name"] = "Citrin des Schwallmatrosen", ["text"] = "Ca. 4 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, 5 Gegner mit einer schneidenden Meeresbrise zu treffen und ihnen so jeweils ( 36 * 10.89 * 1 ) Naturschaden zuzufügen." }
