entries[462541] = { ["name"] = "Kosmischer Riss", ["text"] = "Sofort\nKosmische Trümmer brechen aus der jenseitigen Finsternis aus und fügen Spielercharakteren innerhalb von 6 Metern um den Einschlag 400 körperlichen Schaden sowie 15 Sek. lang alle 1 Sek. 40 zusätzlichen Schattenschaden zu.\n\nBei Ablauf oder wenn ' Kosmischer Riss ' keinen Spielercharakter trifft, wird ' Kosmischer Niederschlag ' ausgelöst.\n\nDieses Gebrechen wird bei Bewegung durch ein ' Schattentor ' entfernt, wodurch ' Verweilender Niederschlag ' ausgelöst wird." }
